    class ActitimeAPIError(Exception):
        """Custom exception for actiTIME API errors with structured information."""

        def __init__(self, status_code: int, key: str, message: str, url: str):
            """
            Initialize the exception.

            Args:
                status_code: HTTP status code
                key: Error key from actiTIME (e.g., "api.error.customer_exists")
                message: Human-readable error message
                url: The URL that caused the error
            """
            self.status_code = status_code
            self.key = key
            self.message = message
            self.url = url
            super().__init__(
                f"actiTIME API Error [{status_code}] at {url}: {key} - {message}"
            )

        @classmethod
        def from_response(
            cls, response: requests.Response, url: str
        ) -> "ActitimeAPIError":
            """
            Factory method to create error from response.

            Args:
                response: The HTTP response object
                url: The URL that was called

            Returns:
                ActitimeAPIError instance
            """
            try:
                error_data = response.json()
                key = error_data.get("key", "unknown_error")
                message = error_data.get("message", response.text)
            except Exception:
                key = "parse_error"
                message = response.text[:500] if response.text else "No response body"

            return cls(response.status_code, key, message, url)


    class RateLimiter:
        """
        Rate limiter for actiTIME API with per-second and per-minute limits.

        actiTIME enforces:
        - 100 requests per second per user account
        - 1000 requests per minute per user account
        - IP ban after 3 failed auth attempts in 10 seconds
        """

        def __init__(
            self, requests_per_second: int = 100, requests_per_minute: int = 1000
        ):
            """
            Initialize the rate limiter.

            Args:
                requests_per_second: Maximum requests per second (default: 100)
                requests_per_minute: Maximum requests per minute (default: 1000)
            """
            self.requests_per_second = requests_per_second
            self.requests_per_minute = requests_per_minute
            self._request_timestamps: List[float] = []
            self._last_request_time: float = 0

        def wait_if_needed(self) -> None:
            """Enforce rate limiting by sleeping if needed."""
            now = time.time()

            # Enforce minimum delay between requests (10ms for 100 req/sec)
            min_delay = 1.0 / self.requests_per_second
            time_since_last = now - self._last_request_time
            if time_since_last < min_delay:
                time.sleep(min_delay - time_since_last)
                now = time.time()

            # Clean up timestamps older than 1 minute
            self._request_timestamps = [
                ts for ts in self._request_timestamps if now - ts < 60
            ]

            # If at minute limit, wait for oldest request to expire
            if len(self._request_timestamps) >= self.requests_per_minute:
                sleep_time = 60 - (now - self._request_timestamps[0])
                if sleep_time > 0:
                    time.sleep(sleep_time)

            self._request_timestamps.append(time.time())
            self._last_request_time = time.time()


