        # Reader Methods - Date Range Endpoints
        # =========================================================================

        def _read_timetrack(
            self,
            start_offset: Dict[str, Any],
            table_options: Dict[str, str],
        ) -> Tuple[Iterator[Dict[str, Any]], Dict[str, Any]]:
            """
            Read timetrack entries with date range filtering.

            The API returns nested structure which is flattened to individual records.

            Optional table_options:
                - dateFrom: Start date (YYYY-MM-DD). Defaults to offset cursor or 90 days ago
                - dateTo: End date (YYYY-MM-DD). Defaults to today
            """
            # Smart defaults for date range
            date_from = table_options.get("dateFrom")
            date_to = table_options.get("dateTo")

            # If not provided, use intelligent defaults
            if not date_from:
                # Use cursor from offset if available, otherwise go back 90 days
                if start_offset and "cursor" in start_offset:
                    date_from = start_offset["cursor"]
                else:
                    date_from = (datetime.now() - timedelta(days=90)).strftime("%Y-%m-%d")

            if not date_to:
                # Default to today
                date_to = datetime.now().strftime("%Y-%m-%d")

            url = f"{self.base_url}/timetrack"
            params: Dict[str, Any] = {
                "dateFrom": date_from,
                "dateTo": date_to,
            }

            # Optional filters
            if table_options.get("userIds"):
                params["userIds"] = table_options["userIds"]
            if table_options.get("taskIds"):
                params["taskIds"] = table_options["taskIds"]

            response = self._make_request_with_retry("GET", url, params=params)

            if response.status_code != 200:
                raise ActitimeAPIError.from_response(response, url)

            data = response.json()

            # Handle timetrack response structure
            # Response format: {"dateFrom": "...", "dateTo": "...", "data": [...]}
            if isinstance(data, dict) and "data" in data:
                items = data.get("data", [])
            elif isinstance(data, dict) and "items" in data:
                items = data.get("items", [])
            elif isinstance(data, list):
                items = data
            else:
                items = []

            # Flatten nested structure - each item has userId, date, and records array
            records: List[Dict[str, Any]] = []
            max_date = start_offset.get("cursor") if start_offset else None

            for user_entry in items:
                # Handle the actual structure from the API
                user_id = user_entry.get("userId")
                date = user_entry.get("date")

                # Get records array, if exists
                entry_records = user_entry.get("records", [])
                if entry_records:
                    for record in entry_records:
                        flattened = {
                            "id": record.get("id"),
                            "userId": user_id,
                            "date": date,
                            "taskId": record.get("taskId"),
                            "time": record.get("time"),
                            "comment": record.get("comment"),
                            "approved": record.get("approved"),
                            "locked": record.get("locked"),
                            "typeOfWorkId": record.get("typeOfWorkId"),
                        }
                        records.append(flattened)
                else:
                    # No nested records - might be flat structure
                    # Try to use the entry directly if it has required fields
                    if user_entry.get("id") is not None or user_entry.get("taskId") is not None:
                        flattened = {
                            "id": user_entry.get("id"),
                            "userId": user_id,
                            "date": date,
                            "taskId": user_entry.get("taskId"),
                            "time": user_entry.get("time"),
                            "comment": user_entry.get("comment"),
                            "approved": user_entry.get("approved"),
                            "locked": user_entry.get("locked"),
                            "typeOfWorkId": user_entry.get("typeOfWorkId"),
                        }
                        records.append(flattened)

                if date and (max_date is None or date > max_date):
                    max_date = date

            next_offset = {"cursor": max_date} if max_date else {}
            return iter(records), next_offset

