        # =========================================================================
        # Reader Methods - Simple Endpoints (Snapshot)
        # =========================================================================

        def _read_simple(
            self,
            endpoint: str,
            allow_not_found: bool = False,
        ) -> Tuple[Iterator[Dict[str, Any]], Dict[str, Any]]:
            """
            Generic reader for simple endpoints without pagination.

            Args:
                endpoint: API endpoint name
                allow_not_found: If True, return empty results for 404 (endpoint may not exist)

            Returns:
                Tuple of (records iterator, empty offset)
            """
            url = f"{self.base_url}/{endpoint}"
            response = self._make_request_with_retry("GET", url)

            if response.status_code == 404 and allow_not_found:
                # Endpoint doesn't exist in this actiTIME instance
                return iter([]), {}

            if response.status_code != 200:
                raise ActitimeAPIError.from_response(response, url)

            data = response.json()

            # Handle paginated response structure with 'items' key
            if isinstance(data, dict) and "items" in data:
                return iter(data.get("items", [])), {}
            elif isinstance(data, list):
                return iter(data), {}
            else:
                # Singleton response (e.g., settings)
                return iter([data]), {}

