        def _read_info(
            self,
            start_offset: Dict[str, Any],
            table_options: Dict[str, str],
        ) -> Tuple[Iterator[Dict[str, Any]], Dict[str, Any]]:
            """
            Read system info (singleton snapshot).

            The /info endpoint returns system settings including company info,
            format settings, enabled features, URLs, and limits.
            """
            records_iter, next_offset = self._read_simple("info")

            def add_synthetic_id(records: Iterator[Dict[str, Any]]) -> Iterator[Dict[str, Any]]:
                """Add synthetic id to each record for primary key requirement."""
                for record in records:
                    record["id"] = "system"
                    yield record

            return add_synthetic_id(records_iter), next_offset

        # =========================================================================
        # Reader Methods - Parent-Child Pattern
        # =========================================================================

        def _read_user_rates(
            self,
            start_offset: Dict[str, Any],
            table_options: Dict[str, str],
        ) -> Tuple[Iterator[Dict[str, Any]], Dict[str, Any]]:
            """
            Read user rates (parent-child pattern).

            This requires fetching all users first, then fetching rates for each user.
            """
            # First, get all users
            users_iter, _ = self._read_users({}, table_options)
            users = list(users_iter)

            records: List[Dict[str, Any]] = []

            for user in users:
                user_id = user.get("id")
                if not user_id:
                    continue

                url = f"{self.base_url}/userRates/{user_id}"
                response = self._make_request_with_retry("GET", url)

                if response.status_code == 404:
                    # User has no rates, skip
                    continue

                if response.status_code != 200:
                    raise ActitimeAPIError.from_response(response, url)

                rates_data = response.json()

                # Handle both list and single object responses
                if isinstance(rates_data, dict):
                    rates_data = [rates_data]

                for rate in rates_data:
                    record = {
                        "userId": user_id,
                        "dateFrom": rate.get("dateFrom"),
                        "regularRate": rate.get("regularRate"),
                        "overtimeRate": rate.get("overtimeRate"),
                        "leaveRates": rate.get("leaveRates"),
                    }
                    records.append(record)

            return iter(records), {}


